WITH exploded AS (SELECT id, log_ts, level, latency_ms, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, value), scored AS (SELECT log_ts, level, latency_ms, value, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY level), 4) AS latency_ms_share, AVG(latency_ms) OVER (ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS latency_ms_avg_30m FROM exploded WHERE HOUR(log_ts) BETWEEN 8 AND 12), filtered AS (SELECT *, CAST(log_ts AS DATE) AS log_ts_day FROM scored WHERE latency_ms BETWEEN 1247 AND 1352), scored_app_logs AS (SELECT log_ts, value, latency_ms_avg_30m, MIN(latency_ms_share) OVER (PARTITION BY level) AS level_min_latency_ms_share, STDDEV_SAMP(latency_ms) OVER (PARTITION BY level) AS level_stddev_samp_latency_ms, AVG(latency_ms_share) OVER (PARTITION BY level) AS level_avg_latency_ms_share FROM filtered), enriched AS (SELECT *, AVG(level_min_latency_ms_share) OVER (ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS level_min_latency_ms_share_avg_30m, SUM(level_avg_latency_ms_share) OVER (ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS level_avg_latency_ms_share_sum_15m, MAX(level_avg_latency_ms_share) OVER (ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS level_avg_latency_ms_share_max_2h FROM scored_app_logs), valid AS (SELECT log_ts, value, level_stddev_samp_latency_ms, level_min_latency_ms_share_avg_30m, level_avg_latency_ms_share_max_2h, level_min_latency_ms_share_avg_30m / NULLIF(level_min_latency_ms_share, 0) AS level_min_latency_ms_share_avg_30m_per_level_min_latency_ms_share FROM enriched WHERE log_ts >= TIMESTAMP '2025-06-01 06:00:00' AND TO_DATE(log_ts) >= '2025-03-30'), scored_app_logs_2 AS (SELECT *, MAX(level_stddev_samp_latency_ms) OVER (ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS level_stddev_samp_latency_ms_max_1h, MAX(level_min_latency_ms_share_avg_30m) OVER (ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS level_min_latency_ms_share_avg_30m_max_2h, PERCENT_RANK() OVER (ORDER BY level_avg_latency_ms_share_max_2h DESC NULLS LAST) AS level_avg_latency_ms_share_max_2h_percent_rank, CUME_DIST() OVER w_grp AS level_min_latency_ms_share_avg_30m_cume_dist FROM valid WINDOW w_grp AS (ORDER BY level_min_latency_ms_share_avg_30m ASC NULLS LAST)) SELECT log_ts, level_stddev_samp_latency_ms, level_avg_latency_ms_share_max_2h, level_min_latency_ms_share_avg_30m_per_level_min_latency_ms_share, level_min_latency_ms_share_avg_30m_max_2h, level_avg_latency_ms_share_max_2h_percent_rank, level_min_latency_ms_share_avg_30m_cume_dist FROM scored_app_logs_2 ORDER BY log_ts DESC NULLS LAST, level_avg_latency_ms_share_max_2h ASC;
